#!/usr/bin/env node
// Pulls PrismPM feature requests into src/docs/requests.generated.ts: open ones ranked by votes and
// recently shipped ones. Run by .github/workflows/sync-prism-docs.yml. Never edit the generated file.
import { writeFile } from "node:fs/promises";

const REPO = "UOR-Foundation/PrismPM";
const headers = { Accept: "application/vnd.github+json", "User-Agent": "uor-site-docs-sync", ...(process.env.GITHUB_TOKEN ? { Authorization: `Bearer ${process.env.GITHUB_TOKEN}` } : {}) };
async function json(url) {
  const r = await fetch(url, { headers });
  if (!r.ok) throw new Error(`${url} → ${r.status}`);
  return r.json();
}

// Feature request feed: open requests ranked by 👍 and recently shipped ones, so agents search before filing and learn when a request lands.
const FEATURE_LABELS = ["kind/feature", "enhancement"];
const issue = (i) => ({ number: i.number, title: i.title, url: i.html_url, state: i.state, votes: i.reactions?.["+1"] ?? 0, labels: i.labels.map((l) => l.name), agent: i.labels.some((l) => l.name === "agent-submitted"), created: i.created_at, closed: i.closed_at, milestone: i.milestone?.title ?? null });
async function search(q) {
  const r = await json(`https://api.github.com/search/issues?q=${encodeURIComponent(q)}&sort=reactions-%2B1&order=desc&per_page=50`);
  return r?.items ?? [];
}
const seen = new Map();
for (const label of FEATURE_LABELS) {
  for (const i of await search(`repo:${REPO} is:issue is:open label:"${label}"`)) seen.set(i.number, issue(i));
  for (const i of await search(`repo:${REPO} is:issue is:closed reason:completed label:"${label}"`)) seen.set(i.number, issue(i));
}
const all = [...seen.values()].filter((i) => !i.labels.includes("tracking"));
const requests = {
  open: all.filter((i) => i.state === "open").sort((a, b) => b.votes - a.votes || a.number - b.number),
  shipped: all.filter((i) => i.state === "closed").sort((a, b) => (b.closed || "").localeCompare(a.closed || "")).slice(0, 25),
};
await writeFile(new URL("../src/docs/requests.generated.ts", import.meta.url), `// Generated by scripts/sync-prism-requests.mjs from ${REPO} issues. Do not edit.\n` +
  `export type PrismRequest = { number: number; title: string; url: string; state: string; votes: number; labels: string[]; agent: boolean; created: string; closed: string | null; milestone: string | null };\n` +
  `export const PRISM_REQUESTS: { open: PrismRequest[]; shipped: PrismRequest[] } = ${JSON.stringify(requests, null, 2)};\n`);
console.log(`Synced ${requests.open.length} open and ${requests.shipped.length} shipped feature requests.`);
